# Let's try a SAT approach with a better encoding

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType

n_vertices = 9
n_labels = 16
edges = [
    (0,1), (0,2), (1,2),  # clique 0
    (3,4), (3,5), (4,5),  # clique 1
    (6,7), (6,8), (7,8),  # clique 2
    (0,3), (1,4), (2,5),  # between 0 and 1
    (3,6), (4,7), (5,8),  # between 1 and 2
]
n_edges = len(edges)

solver = Glucose3()

# Variable for vertex v gets label l
var_vl = {}
idx = 1
for v in range(n_vertices):
    for l in range(n_labels):
        var_vl[(v, l)] = idx
        idx += 1

# Variable for edge e has difference d
var_ed = {}
for e_idx, (u, v) in enumerate(edges):
    for d in range(1, n_labels):  # d = 1..15
        var_ed[(e_idx, d)] = idx
        idx += 1

# Each vertex gets exactly one label
for v in range(n_vertices):
    # at least one
    solver.add_clause([var_vl[(v, l)] for l in range(n_labels)])
    # at most one
    for l1 in range(n_labels):
        for l2 in range(l1+1, n_labels):
            solver.add_clause([-var_vl[(v, l1)], -var_vl[(v, l2)]])

# Each label used at most once
for l in range(n_labels):
    for v1 in range(n_vertices):
        for v2 in range(v1+1, n_vertices):
            solver.add_clause([-var_vl[(v1, l)], -var_vl[(v2, l)]])

# Each edge gets exactly one difference
for e_idx in range(n_edges):
    solver.add_clause([var_ed[(e_idx, d)] for d in range(1, n_labels)])
    for d1 in range(1, n_labels):
        for d2 in range(d1+1, n_labels):
            solver.add_clause([-var_ed[(e_idx, d1)], -var_ed[(e_idx, d2)]])

# Each difference used exactly once (since 15 edges, 15 differences)
for d in range(1, n_labels):
    # at least one
    solver.add_clause([var_ed[(e_idx, d)] for e_idx in range(n_edges)])
    # at most one
    for e1 in range(n_edges):
        for e2 in range(e1+1, n_edges):
            solver.add_clause([-var_ed[(e1, d)], -var_ed[(e2, d)]])

# Now the connection: if vertex u has label l and vertex v has label l', 
# then edge (u,v) must have difference |l-l'|
# For each edge (u,v), for each pair of labels (l,l') with l != l':
# if var_vl[(u,l)] and var_vl[(v,l')] then var_ed[(e_idx, |l-l'|)]
# Equivalently: (-var_vl[(u,l)] OR -var_vl[(v,l')] OR var_ed[(e_idx, |l-l'|)])

for e_idx, (u, v) in enumerate(edges):
    for l in range(n_labels):
        for lp in range(n_labels):
            if l == lp:
                continue
            d = abs(l - lp)
            solver.add_clause([-var_vl[(u, l)], -var_vl[(v, lp)], var_ed[(e_idx, d)]])

print(f"Total variables: {idx-1}")
print(f"Solving...")
result = solver.solve()
print(f"Result: {result}")

if result:
    model = solver.get_model()
    # Extract vertex labels
    labels = {}
    for v in range(n_vertices):
        for l in range(n_labels):
            if model[var_vl[(v, l)] - 1] > 0:
                labels[v] = l
                break

    print(f"Labels: {labels}")

    # Print in order: clique 0 vertices 0,1,2; clique 1 vertices 3,4,5; clique 2 vertices 6,7,8
    result_list = [labels[i] for i in range(9)]
    print(f"Result list: {result_list}")

    # Verify
    edge_diffs = set()
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        edge_diffs.add(d)
    print(f"Edge differences: {sorted(edge_diffs)}")
    print(f"All distinct: {len(edge_diffs) == 15}")
    print(f"Min: {min(edge_diffs)}, Max: {max(edge_diffs)}")
else:
    print("UNSATISFIABLE")
